<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('reports.view');$from=(string)input('from',date('Y-m-d',strtotime('-30 days')));$to=(string)input('to',date('Y-m-d'));if(!valid_date($from)||!valid_date($to)){$from=date('Y-m-d',strtotime('-30 days'));$to=date('Y-m-d');flash('error','Invalid report date range.');}$stmt=db()->prepare('SELECT w.withdrawal_id,u.name,u.mobile,w.amount,w.payment_method,w.payment_reference,w.status,w.risk_level,w.requested_at FROM withdrawals w JOIN users u ON u.id=w.user_id WHERE w.requested_at>=? AND w.requested_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY w.id DESC LIMIT 5000');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();if(input('export')==='csv'){require_permission('reports.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="withdrawals-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Withdrawal ID','User','Mobile','Amount','Method','Payment reference','Status','Risk','Requested'],',','"','\\');foreach($rows as $r)fputcsv($out,csv_row($r),',','"','\\');audit_log((int)admin()['id'],'REPORT_EXPORT','reports','withdrawals',null,['from'=>$from,'to'=>$to,'rows'=>count($rows)]);exit;}$pageTitle='Withdrawal report';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Withdrawal activity</h2><div class="actions"><a href="<?=e(app_url('/admin/reports/transactions.php'))?>">Transactions</a><a href="<?=e(app_url('/admin/reports/security.php'))?>">Security</a></div></div><form class="filters"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Run report</button><?php if(can('reports.export')):?><button class="btn secondary" name="export" value="csv">Export CSV</button><?php endif?></form><div class="table-wrap"><table><thead><tr><th>Withdrawal</th><th>User</th><th>Amount</th><th>Method</th><th>Status</th><th>Risk</th><th>Requested</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['withdrawal_id'])?></td><td><?=e($r['name'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['payment_method'])?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['risk_level'])?></td><td><?=e($r['requested_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
